Generate print test statements for this code to test edge cases.
-Duplicate vowels in a row.
-Vowel substrings that are the same length.
-Strings with no vowels
-Also any other side cases you can think of.

def solve(s):
    prev_vowel_i = None 
    longest_len = 1

    for i in range(len(s)):
        if s[i] in 'aeiou':
            if prev_vowel_i is None:
                prev_vowel_i = i
            else:
                vowel_len = i-prev_vowel_i+1
                longest_len = max(longest_len, vowel_len)
        else:
            prev_vowel_i = None

    return longest_len

